-- 241 · Compras en DÓLARES con tarjeta (cuotas en $ 0): se pasan a PESOS con el TC que usó la tarjeta (DATOS) — A-BUG-1584.
-- OK JMS 10/11: «D1 sí, dale con las 45 y vos no tenés esos extractos?» (los PDF de la VISA PAM daban el TC de las otras 15).
-- Criterio JMS: «si se pagó en pesos debe ponerse el monto exacto pagado en pesos… saber o calcular el TC que usó la tarjeta».
-- TC: MA y MSA (y PAM ago-25 / feb-26) = pesos debitados por el Galicia ÷ «SU PAGO EN USD» (el saldo en US$ se pagó en pesos);
-- PAM sep-25 a abr-26 = el TC del renglón «SALDO ANTERIOR … TCxxxx» del PDF del resumen siguiente.
-- Control (verificado antes de correr): por resumen, la suma de las cuotas en pesos = el débito del banco / lo que dice el PDF.
-- 60 cuotas (de 61: falta la de VISA PAM cierre 30/04/26, US$ 2,40, sin el PDF 26-05). Estado y vínculo no se tocan.
-- Foto: scripts/241-foto-antes.json · Excel de respaldo: Balance/respaldos/…ANTES script 241 · Deshacer: 241-…-deshacer.sql.
begin;
with tc(tarjeta, cierre, tc, fuente) as (values
 ('VISA MA','2025-11-27'::date,1460,'pago 05/12/25 $ 479.551,60'),('VISA MA','2025-12-31',1475,'pago 09/01/26 $ 38.084,50'),('VISA MA','2026-01-29',1450,'pago 06/02/26 $ 37.134,50'),
 ('VISA MA','2026-02-26',1435,'pago 06/03/26 $ 37.826,60'),('VISA MA','2026-03-26',1415,'pago 06/04/26 $ 37.341,85'),('VISA MA','2026-04-30',1415,'pago 08/05/26 $ 66.306,90'),
 ('VISA MA','2026-05-28',1460,'pago 05/06/26 $ 67.714,80'),('VISA MA','2026-07-02',1505,'pago 13/07/26 $ 38.994,55'),
 ('VISA MSA','2025-08-28',1440,'pago 08/09/25 $ 274.809,60'),('VISA MSA','2025-10-02',1370,'pago 13/10/25 $ 41.031,50'),('VISA MSA','2025-10-30',1450,'pago 10/11/25 $ 43.427,50'),
 ('VISA MSA','2025-11-27',1460,'pago 09/12/25 $ 43.727,00'),('VISA MSA','2025-12-31',1470,'pago 12/01/26 $ 220.250,10'),('VISA MSA','2026-01-29',1440,'pago 09/02/26 $ 43.128,00'),
 ('VISA PAM','2025-07-31',1340,'pago 06/08/25 $ 73.673,20'),('VISA PAM','2025-08-28',1385,'resumen VISA PAM 25-09, TC1385'),('VISA PAM','2025-10-02',1370,'resumen VISA PAM 25-10, TC1370'),
 ('VISA PAM','2025-10-30',1450,'resumen VISA PAM 25-11, TC1450'),('VISA PAM','2025-11-27',1460,'resumen VISA PAM 25-12, TC1460'),('VISA PAM','2025-12-31',1475,'resumen VISA PAM 26-01, TC1475'),
 ('VISA PAM','2026-01-29',1450,'pago 06/02/26 $ 6.264,00'),('VISA PAM','2026-02-26',1435,'resumen VISA PAM 26-03, TC1435'),('VISA PAM','2026-03-26',1415,'resumen VISA PAM 26-04, TC1415')),
m as (select 'VISA PAM' tarjeta, template_cuota_id v, debitos_usd - creditos_usd usd, fecha_cierre from pam.tarjeta_visa where tipo_fila='movimiento' and debitos=0 and creditos=0 and (debitos_usd<>0 or creditos_usd<>0)
  union all select 'VISA MA', template_cuota_id, debitos_usd - creditos_usd, fecha_cierre from ma.tarjeta_visa where tipo_fila='movimiento' and debitos=0 and creditos=0 and (debitos_usd<>0 or creditos_usd<>0)
  union all select 'VISA MSA', template_cuota_id, debitos_usd - creditos_usd, fecha_cierre from msa.tarjeta_visa_business where tipo_fila='movimiento' and debitos=0 and creditos=0 and (debitos_usd<>0 or creditos_usd<>0)),
x as (select m.v id, round(m.usd * tc.tc, 2) pesos, m.usd, tc.tc, tc.fuente from m join tc on tc.tarjeta = m.tarjeta and tc.cierre = m.fecha_cierre)
update public.cuotas_egresos_sin_factura c
   set monto = x.pesos,
       descripcion = concat_ws(' · ', nullif(c.descripcion, ''), 'US$ ' || replace(to_char(x.usd, 'FM999990.00'), '.', ',') || ' × TC ' || x.tc || ' (' || x.fuente || ') [script 241]')
  from x
 where c.id = x.id and c.id in ('0261931c-f474-43e0-b0ed-f0a708a8a92a', '04077c30-478d-48f1-9150-ff62a845a5f5', '04ca472c-d70f-4f04-9163-5279f8894e53', '06dc4761-446f-49ab-a1c1-649f59450a74', '0e90d1d8-ac75-44d8-9d98-371f6bbc68ff', '102cdbae-05b4-45a6-bf68-1e2247203d5f', '247c17b7-1171-4f4f-afa8-54ecdf9970e5', '26a30560-8c36-40cf-a0d5-c4a86ad9cdf5', '27d79d8e-f3d2-489b-a5d4-36b9efd40f9d', '2bc0c976-8a8f-4301-a6e8-28688c871f82', '2cbfa723-e3a9-4bfe-a0e0-373deeb38a3e', '2f67656b-a357-406c-994c-21a1d3cb34a4', '300ac581-a72d-4a23-9a2c-6a048574bc37', '35d0af4b-786b-448a-b0cf-2a7e68565fb4', '3831fd5a-5d6a-4a48-be44-5bc12b016331', '4132fdbc-86b0-4281-88c7-881f01197711', '43e908c0-2e5c-4bfe-aeaf-6b05ffac8d3f', '4bfa3621-8f79-4680-9862-488689480e56', '4f110cab-5696-42b2-92cd-fe1da69b553a', '5463459a-0e0a-4e51-8038-188c6642909f', '57582a92-2b45-4593-bd27-218e63e17ef6', '5c656162-2e95-4f95-bf5e-4da4c1720533', '5d41889c-7ecd-47b3-b18a-c02d73b86f64', '6531fa3c-07e4-40dc-a73c-80861d1b4c70', '67261a81-b0c0-4a39-872c-f846d8234603', '68b9756b-4f91-4065-a86e-9eadb6d3a73a', '6cd44dfe-924f-435a-be70-1e6b319171bf', '6dc51cbe-d1f1-4633-bff4-a1b02a914856', '7244316f-000f-4755-bb69-1a2937964b5f', '79230a5e-133a-4c3f-8d4e-ce44cf494123', '7b777840-a4fd-4ac9-bbb6-52e99b2b6eee', '82b162b2-03c0-4c03-a618-02597365ce2b', '83bbae60-1688-4e51-b448-827ca0ddc24f', '8720783b-c8e4-464b-9d39-c8dbcd415881', '8b54ba78-9f38-4dad-b44b-17c77eac23ad', '8d1d894a-bc24-4721-a31a-b3019efb39d1', '8f170acb-cacd-43b1-94ba-07a808899bf7', '91a1b235-5dcb-4731-9682-3f633b07bdab', '9434596b-fcc1-47cb-8784-5594226f708f', '97e27127-7d63-4cd8-8420-97c0dd6e8a73', 'a016f9af-8df7-4555-a61c-a3bffbfbe70b', 'a33decf7-8730-42e9-9600-7798d357d187', 'a48fda3c-aae8-4e24-985d-32093f38963a', 'a7f50d73-e5aa-4151-ad35-44541bf6af72', 'b61ac8f2-717b-4849-a6c1-512d0d901db2', 'ba56631f-bfde-4cd6-aa8c-ea80820a5f89', 'c35eda56-01ca-4c57-986a-7e4676a533a0', 'c918a672-83f1-4348-bdad-02711998cce1', 'c9b9cf14-87c6-402a-9bfa-e16c35421c13', 'cd7c07f